double totalipatvshkursi = 0;
double cmimiMeTvsh;
double cmimPaTvsh;  
  double totalPaTvsh; 
System.Collections.Generic.List<object[]> artikujt = new System.Collections.Generic.List<object[]>();
     double likujdimi = 0;
 double totalimetvsh = 0;
 float distancaLartesi = 20F;
        float koordinataX = 111.05F;
        float koordinataLlogariX = 191.05F;
        float koordinataY = 105F;


private void xrTable11_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
  int i = 0;
            if (artikujt.Count > 0)
            {
                xrTable11.Rows.Clear();
                foreach (object[] obj in artikujt)
                {
                    XRTableRow rr = new XRTableRow();
                    rr.Borders = DevExpress.XtraPrinting.BorderSide.Bottom;
                    rr.HeightF = 25f;
                    XRTableCell nr = new XRTableCell();
                    nr.WidthF = 59.96f;
                    nr.Name = "nr" + i.ToString();
                    nr.Text = (i+1).ToString();
                    rr.Cells.Add(nr);

                    XRTableCell kodi = new XRTableCell();
                    kodi.WidthF = 59.96f;
                    kodi.Name = "Kodi" + i.ToString();
                    kodi.Text = obj[0].ToString();
                    rr.Cells.Add(kodi);

                    XRTableCell pershkrimi = new XRTableCell();
                    pershkrimi.WidthF = 396.29f;
                    pershkrimi.Name = "pershkrimi" + i.ToString();
                    pershkrimi.Text = obj[1].ToString();
                    rr.Cells.Add(pershkrimi);

                    XRTableCell sasia = new XRTableCell();
                    sasia.WidthF = 55.83f;
                    sasia.Name = "Sasia" + i.ToString();
                    sasia.Text = obj[2].ToString();
                    rr.Cells.Add(sasia);

                    XRTableCell Njesia = new XRTableCell();
                    Njesia.WidthF = 89f;
                    Njesia.Name = "PERSHKRIMNJESIA" + i.ToString();
                    Njesia.Text = String.Format("{0:#,#}", obj[3]);
                    rr.Cells.Add(Njesia);

                    xrTable11.Rows.Insert(i, rr);
                    i++;
                }
            }
}


private void label15_SummaryGetResult(object sender, DevExpress.XtraReports.UI.SummaryGetResultEventArgs e) {
e.Result = (totalipatvshkursi - Convert.ToDouble(GetCurrentColumnValue("ZBRITJE")) - Convert.ToDouble(GetCurrentColumnValue("TVSHTOTAL"))) * Convert.ToDouble(GetCurrentColumnValue("KURSI"));
            e.Handled = true;
}

private void label15_SummaryReset(object sender, System.EventArgs e) {
totalipatvshkursi = 0;
}

private void label15_SummaryRowChanged(object sender, System.EventArgs e) {
 totalipatvshkursi += Convert.ToDouble(GetCurrentColumnValue("VLEFTAPATVSH"));
}



private void tableCell14_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
 int brutoNetoNivelCmimi = Convert.ToInt32(GetCurrentColumnValue("BRUTONETONIVELCMIMI"));
            if (brutoNetoNivelCmimi == 1)
            {
                cmimiMeTvsh = Convert.ToDouble(GetCurrentColumnValue("CMIMI"));
                if (GetCurrentColumnValue("tvsh").ToString() != "")
                    cmimPaTvsh = Convert.ToDouble(GetCurrentColumnValue("CMIMI")) * (1 - Math.Round(Convert.ToDouble(GetCurrentColumnValue("tvsh")), 2));
                else 
                    cmimPaTvsh = Convert.ToDouble(GetCurrentColumnValue("CMIMI"));
                tableCell14.Text = cmimPaTvsh.ToString("################################0.00");
                  }
            else
            {
                cmimPaTvsh = Convert.ToDouble(GetCurrentColumnValue("CMIMI"));
               tableCell14.Text = cmimPaTvsh.ToString("################################0.00");
                if (GetCurrentColumnValue("tvsh").ToString() != "")
                    cmimiMeTvsh = Convert.ToDouble(GetCurrentColumnValue("CMIMI")) * (1 + Math.Round(Convert.ToDouble(GetCurrentColumnValue("tvsh")), 2));
                else cmimiMeTvsh = Convert.ToDouble(GetCurrentColumnValue("CMIMI"));
                 }
            totalPaTvsh += Convert.ToDouble(GetCurrentColumnValue("VLEFTAPATVSH"));
}
private void xrLabel36_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
object monedhaBaze = GetCurrentColumnValue("MONEDHANDERMARJE");
            string detyrimi = "Detyrimi LEK";
            if(monedhaBaze != null && monedhaBaze != DBNull.Value)
                detyrimi = "Detyrimi " + monedhaBaze.ToString();
            xrLabel36.Text = detyrimi;

}

private void Rap_FatureShitje_DeltaKosove_SePDeFn_131341430201394170_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
    AlphaWebReports.raporteUtil.shfaqLlogariteBankare((int)this.Parameters["parameterIdNderm"].Value, (int)this.Parameters["arameterIdPerdoruesi"].Value, null, null, distancaLartesi, koordinataY, koordinataX, koordinataLlogariX,
               "Arial", 8F, System.Drawing.FontStyle.Regular, Color.Black, 80F, 20F, 203.55F, 20F, 0, DevExpress.XtraPrinting.BorderSide.Bottom);

}

private void tableCell10_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
object[] obj = new object[4];
            if (GetCurrentColumnValue("KODI") != null)
                obj[0] = GetCurrentColumnValue("KODI");
            if (GetCurrentColumnValue("PERSHKRIMI") != null)
                obj[1] = GetCurrentColumnValue("PERSHKRIMI");
            else obj[1] = "";
            if (GetCurrentColumnValue("SASIA") != null)
                obj[2] = GetCurrentColumnValue("SASIA");
            else obj[2] = "";
            if (GetCurrentColumnValue("PERSHKRIMNJESIA") != null)
                obj[3] = GetCurrentColumnValue("PERSHKRIMNJESIA");
            else obj[3] = "";
            artikujt.Add(obj);

}
